return {
  grant: {
    hook: "activated", label: "Ward Ally",
    available: (H, actor) => H.condition.has(actor, "sheltered")
      && actor.system.health.wounds.value > 0,
    async promptOnPlayer(H, actor) {
      const allies = H.zone.allies(actor);
      if (!allies.length) {
        ui.notifications.warn("Ward: no allies in your area.");
        return false;
      }
      const targetId = await H.ask.one({
        title: "Ward: Choose Hunter", label: "Ward",
        options: allies.map(h => ({ value: h.id, label: h.name })),
      });
      if (!targetId) return false;
      await H.resource.adjust(actor, { wounds: -1 });
      await actor.setFlag("hollows", "ward", { targetId });
      await H.chat.post(`${actor.name} wards ${game.actors.get(targetId).name} (Ward).`, actor);
      return true;
    },
  },
  reduce: {
    hook: "incomingDamage", scope: "targetState", damageSource: "entity", timing: "postMitigation",
    aura: true, group: "book.t1.ward.reduce",
    run(H, actor, ctx) {
      const selfWard = ctx.carrierIds.includes(actor.id)
        && H.condition.has(actor, "sheltered") && !actor.getFlag("hollows", "ward");
      const grantedWard = ctx.carrierIds.some(id => game.actors.get(id).getFlag("hollows", "ward")?.targetId === actor.id);
      if (!selfWard && !grantedWard) return null;
      const reduction = ctx.shelteredApplied ? 1 : 2;
      return { damageValue: Math.max(0, ctx.damageValue - reduction), note: `Ward: -${reduction}` };
    },
  },
  reset: {
    hook: "interceptor", event: "combat-reset-hunter",
    run: (H, actor) => actor.unsetFlag("hollows", "ward"),
  },
  clear: {
    hook: "onEvent", event: { type: "turnEnd" }, aura: true, group: "book.t1.ward.clear",
    async run(H, actor, ctx) {
      for (const id of ctx.carrierIds) {
        const carrier = game.actors.get(id);
        if (carrier.getFlag("hollows", "ward")?.targetId === actor.id) await carrier.unsetFlag("hollows", "ward");
      }
    },
  },
};
